const members = $input.all();

// Get today's date in YYYY-MM-DD format (India timezone)
const today = new Date().toLocaleDateString("en-CA", {
  timeZone: "Asia/Kolkata"
});

// Reminder days
const reminderDays = [7, 3, 1, 0];

const results = [];

for (const item of members) {
  const member = item.json;

  // Only process active memberships
  if (member.Membership_Status !== "Active") {
    continue;
  }

  if (!member.Expiry_Date) {
    continue;
  }

  // Convert expiry date into UTC midnight
  const [year, month, day] = member.Expiry_Date
    .split("-")
    .map(Number);

  const expiryDate = Date.UTC(year, month - 1, day);

  const [todayYear, todayMonth, todayDay] = today
    .split("-")
    .map(Number);

  const todayDate = Date.UTC(
    todayYear,
    todayMonth - 1,
    todayDay
  );

  // Calculate remaining days
  const daysRemaining = Math.round(
    (expiryDate - todayDate) / (1000 * 60 * 60 * 24)
  );

  // Check whether a reminder is required
  if (reminderDays.includes(daysRemaining)) {
    results.push({
      json: {
        Member_ID: member.Member_ID,
        Name: member.Name,
        Phone: member.Phone,
        Expiry_Date: member.Expiry_Date,
        Days_Remaining: daysRemaining,
        Reminder_Type:
          daysRemaining === 7 ? "7-Day Reminder" :
          daysRemaining === 3 ? "3-Day Reminder" :
          daysRemaining === 1 ? "1-Day Reminder" :
          "Expiry Today"
      }
    });
  }
}

return results;

